    durationFa: "\u067E\u0627\u06CC\u062F\u0627\u0631 \u0648 \u0645\u0627\u0646\u062F\u06AF\u0627\u0631 \u062F\u0631 \u0633\u0627\u0644\u200C\u0647\u0627\u06CC \u0631\u0634\u062F.",
    onsetFa: "\u062F\u0648\u0631\u0647\u0654 \u0627\u0628\u062A\u062F\u0627\u06CC\u06CC \u0631\u0634\u062F.",
    exclusionsFa: ["\u06A9\u0645\u200C\u0634\u0646\u0648\u0627\u06CC\u06CC", "\u0646\u0627\u0631\u0633\u0627\u06CC\u06CC \u0641\u06A9\u0631\u06CC", "\u0627\u062E\u062A\u0644\u0627\u0644 \u062D\u0631\u06A9\u062A\u06CC \u062F\u0647\u0627\u0646"],
