    coreDeficit: "\u0627\u0631\u062A\u0628\u0627\u0637 \u0648 \u067E\u0631\u062F\u0627\u0632\u0634 \u062D\u0633\u06CC",
    homeSigns: [
      "\u062A\u0645\u0627\u0633 \u0686\u0634\u0645\u06CC \u06A9\u0645 \u0627\u0633\u062A \u06CC\u0627 \u0628\u0647\u200C\u0638\u0627\u0647\u0631 \u0627\u0632 \u0634\u0645\u0627 \xAB\u0641\u0631\u0627\u0631\xBB \u0645\u06CC\u200C\u06A9\u0646\u062F \u0648\u0642\u062A\u06CC \u062D\u0631\u0641 \u0645\u06CC\u200C\u0632\u0646\u06CC\u062F.",
      "\u0628\u0647 \u0635\u062F\u0627\u060C \u0646\u0648\u0631 \u06CC\u0627 \u0628\u0627\u0641\u062A\u200C\u0647\u0627\u06CC \u062E\u0627\u0635 \u0648\u0627\u06A9\u0646\u0634 \u0642\u0648\u06CC \u0645\u06CC\u200C\u062F\u0647\u062F: \u062F\u0633\u062A\u200C\u0647\u0627 \u0631\u0627 \u0631\u0648\u06CC \u06AF\u0648\u0634 \u0645\u06CC\u200C\u06AF\u0630\u0627\u0631\u062F \u06CC\u0627 \u0632\u0648\u062F \u0639\u0635\u0628\u06CC \u0645\u06CC\u200C\u0634\u0648\u062F."
    ],
    schoolSigns: [
      "\u062C\u0645\u0644\u0627\u062A \u0627\u0633\u062A\u0639\u0627\u0631\u06CC \u0648 \u0637\u0646\u0632 \u0631\u0627 \u0633\u0627\u062F\u0647\u200C\u0637\u0644\u0628\u0627\u0646\u0647 \u0645\u06CC\u200C\u0641\u0647\u0645\u062F\u061B \u062F\u0633\u062A\u0648\u0631\u0627\u0644\u0639\u0645\u0644 \u0628\u0627\u06CC\u062F \u0631\u0648\u0634\u0646 \u0648 \u0628\u062F\u0648\u0646 \u0627\u06CC\u062C\u0627\u0632 \u0628\u0627\u0634\u062F.",
      "\u0646\u0648\u0628\u062A\u200C\u06AF\u06CC\u0631\u06CC \u062F\u0631 \u06AF\u0641\u062A\u200C\u0648\u06AF\u0648 \u0648 \u0628\u0627\u0632\u06CC \u06AF\u0631\u0648\u0647\u06CC \u0628\u0631\u0627\u06CC\u0634 \u062F\u0634\u0648\u0627\u0631 \u0627\u0633\u062A."
    ],
    differentials: ["\u0627\u062E\u062A\u0644\u0627\u0644 \u0632\u0628\u0627\u0646\u06CC (\u0641\u0647\u0645/\u0628\u06CC\u0627\u0646 \u0645\u062E\u062A\u0635 \u0632\u0628\u0627\u0646\u060C \u0628\u062F\u0648\u0646 \u0627\u0644\u06AF\u0648\u06CC \u062A\u06A9\u0631\u0627\u0631\u06CC/\u062D\u0633\u06CC)", "\u0646\u0627\u0631\u0633\u0627\u06CC\u06CC \u0641\u06A9\u0631\u06CC \u0628\u0647\u200C\u062A\u0646\u0647\u0627\u06CC\u06CC", "\u0627\u0636\u0637\u0631\u0627\u0628 \u0627\u062C\u062A\u0645\u0627\u0639\u06CC \u0628\u0647\u200C\u062A\u0646\u0647\u0627\u06CC\u06CC"],
    instruments: ["ce-asd-criteria-v1"],
    probes: [],
    exercises: [
      { title: "\u062A\u0627\u0628\u0644\u0648\u06CC \u067E\u06CC\u0634\u200C\u0628\u06CC\u0646\u06CC \u0631\u0648\u0632", description: "\u0628\u0631\u0646\u0627\u0645\u0647\u0654 \u0631\u0648\u0632 \u0628\u0627 \u062A\u0635\u0648\u06CC\u0631\u060C \u0627\u0632 \u0642\u0628\u0644 \u062F\u06CC\u062F\u0647 \u0634\u0648\u062F\u061B \u067E\u06CC\u0634\u200C\u0628\u06CC\u0646\u06CC\u200C\u067E\u0630\u06CC\u0631\u06CC \u067E\u0644 \u0627\u0631\u062A\u0628\u0627\u0637 \u0627\u0633\u062A.", minutes: 5 },
      { title: "\u0628\u0627\u0632\u06CC \u0646\u0648\u0628\u062A\u200C\u06AF\u06CC\u0631\u06CC", description: "\u0628\u0627\u0632\u06CC \u0633\u0627\u062F\u0647\u0654 \u0646\u0648\u0628\u062A\u06CC \u0628\u0627 \u0642\u0627\u0639\u062F\u0647\u0654 \u062F\u06CC\u062F\u0627\u0631\u06CC\u061B \u0647\u0645\u200C\u0686\u0634\u0645\u06CC \u062A\u0645\u0631\u06CC\u0646 \u0645\u06CC\u200C\u0634\u0648\u062F.", minutes: 7 },
      { title: "\u0642\u0635\u0647\u0654 \u0627\u062C\u062A\u0645\u0627\u0639\u06CC", description: "\u0642\u0635\u0647\u0654 \u06A9\u0648\u062A\u0627\u0647 \u0627\u0632 \u0645\u0648\u0642\u0639\u06CC\u062A \u0645\u0634\u06A9\u0644\u200C\u0633\u0627\u0632 \u0628\u0627 \u0648\u0627\u06A9\u0646\u0634 \u062F\u0631\u0633\u062A\u061B \u0642\u0628\u0644 \u0627\u0632 \u0645\u0648\u0642\u0639\u06CC\u062A \u0648\u0627\u0642\u0639\u06CC \u062E\u0648\u0627\u0646\u062F\u0647 \u0634\u0648\u062F.", minutes: 8 }
    ],
    path: STANDARD_PATH,
    texts: {
      saw: "\u0686\u06A9\u200C\u0644\u06CC\u0633\u062A \u0645\u0644\u0627\u06A9\u06CC \u0627\u062A\u06CC\u0633\u0645 (\u0645\u0644\u0627\u06A9\u200C\u0647\u0627\u06CC A \u0648 B) \u0627\u0632 \u0647\u0631 \u062F\u0648 \u0645\u0631\u062C\u0639 \u0628\u0631\u0631\u0633\u06CC \u0634\u062F\u0647 \u0627\u0633\u062A.",
      means: "\u0642\u0627\u0639\u062F\u0647\u0654 DSM \xAB\u0647\u0631 \u0633\u0647 \u0645\u0644\u0627\u06A9 A + \u062D\u062F\u0627\u0642\u0644 \u062F\u0648 \u0627\u0632 \u0686\u0647\u0627\u0631 \u0645\u0644\u0627\u06A9 B\xBB \u0633\u0646\u062C\u06CC\u062F\u0647 \u0645\u06CC\u200C\u0634\u0648\u062F\u061B \u0627\u06CC\u0646 \u0686\u06A9\u200C\u0644\u06CC\u0633\u062A \u063A\u0631\u0628\u0627\u0644 \u0627\u0633\u062A \u0648 \u062A\u0634\u062E\u06CC\u0635 \u0646\u06CC\u0633\u062A.",
      next: "\u0627\u06AF\u0631 \u0645\u0644\u0627\u06A9\u200C\u0647\u0627 \u0628\u0631\u0642\u0631\u0627\u0631\u0646\u062F\u060C \u0627\u0631\u062C\u0627\u0639 \u062A\u062E\u0635\u0635\u06CC \u0627\u062A\u06CC\u0633\u0645 \u0648 \u062C\u0644\u0633\u0647\u0654 \u06A9\u0645\u06CC\u0633\u06CC\u0648\u0646 \u0631\u0627 \u0628\u0686\u06CC\u0646\u06CC\u062F\u061B \u062A\u0627\u0628\u0644\u0648\u06CC \u067E\u06CC\u0634\u200C\u0628\u06CC\u0646\u06CC \u0631\u0627 \u0647\u0645\u06CC\u0646 \u062D\u0627\u0644\u0627 \u062F\u0631 \u062E\u0627\u0646\u0647 \u0634\u0631\u0648\u0639 \u06A9\u0646\u06CC\u062F."
    }
